use vstd::prelude::*;

verus! {
    // Specification for the function that checks if a number is even
    spec fn is_even(x: i32) -> bool {
        x % 2 == 0
    }

    // Function to remove odd numbers from the input array
    fn remove_odd_numbers(arr: &[i32]) -> Vec<i32>
        ensures
            forall |x: i32| (x in arr && is_even(x)) ==> (x in result),
            result.len() <= arr.len(),
    {
        let mut result: Vec<i32> = Vec::new();
        let mut idx: usize = 0;

        // Iterate through the input array
        while idx < arr.len()
            invariant
                idx <= arr.len(),
                result.len() <= arr.len(),
                forall |x: i32| (x in arr && is_even(x)) ==> (x in result),
        {
            // Check if the current element is even
            if is_even(arr[idx]) {
                // Push the even element to the result vector
                result.push(arr[idx]);
            }
            idx = idx + 1; // Move to the next index
        }
        result // Return the result vector
    }
}
